    case idle
    case reading(requestId: UInt64, url: String
    )
    case verified(deviceId: String, environmentId: String, catalogVersion: UInt16, url: String, route: RouteObservation
    )
    case rejected(reason: RejectReason, detail: String, route: RouteObservation?
    )
