            FfiConverterTypeRejectReason.write(reason, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            FfiConverterOptionTypeRouteObservation.write(route, into: &buf)
            
        
        case .cancelled:
            writeInt(&buf, Int32(5))
        
        }
    }
